// ─── START: components/color_picker.js ───
class ColorPicker {
  /**
   * @param {{
   *   value: string,
   *   onChange: (colorName: string) => void,
   *   label?: string,
   *   allowAuto?: boolean,
   * }} opts
   */
  constructor({ value = '', onChange, label = 'Farbe', allowAuto = true }) {
    this.value = value || '';
    this.onChange = onChange;
    this.label = label;
    this.allowAuto = allowAuto;
    this.isOpen = false;

    this._onDocClick = (e) => {
      if (!e.composedPath().includes(this.el)) this._close();
    };

    this._build();
  }

  _build() {
    this.swatchDot = h('span', { class: 'cp-dot' });
    this.labelEl = h('span', { class: 'cp-label' });
    this.chevron = icon('mdi:chevron-down', 'cp-chevron');

    this.box = h('button', {
      type: 'button',
      class: 'cp-box',
      onClick: (e) => { e.stopPropagation(); this._toggle(); },
    }, this.swatchDot, this.labelEl, this.chevron);

    this.optionsList = h('div', { class: 'cp-list' });
    this.dropdown = h('div', { class: 'cp-dropdown', hidden: true }, this.optionsList);

    this.el = h('div', { class: 'color-picker' }, this.box, this.dropdown);
    this._updateBox();
  }

  _setValue(val) {
    this.value = val;
    this._updateBox();
    this.onChange?.(val);
    this._close();
  }

  _updateBox() {
    const hex = resolveColor(this.value);
    const label = COLOR_LABELS_DE[this.value] || this.value || 'Automatisch';
    this.labelEl.textContent = label;
    if (hex) {
      this.swatchDot.style.background = hex;
      this.swatchDot.style.boxShadow = `0 0 8px ${hex}88`;
    } else {
      this.swatchDot.style.background = 'var(--cd-accent)';
      this.swatchDot.style.boxShadow = 'none';
    }
  }

  _toggle() {
    if (this.isOpen) this._close();
    else this._open();
  }

  _open() {
    if (this.isOpen) return;
    this.isOpen = true;
    this.dropdown.hidden = false;
    this.box.dataset.open = '';
    this._renderOptions();
    
    setTimeout(() => document.addEventListener('pointerdown', this._onDocClick), 20);
  }

  _close() {
    if (!this.isOpen) return;
    this.isOpen = false;
    this.dropdown.hidden = true;
    delete this.box.dataset.open;
    document.removeEventListener('pointerdown', this._onDocClick);
  }

  _renderOptions() {
    const list = [];
    if (this.allowAuto) {
      list.push(['', 'Automatisch', 'var(--cd-accent)']);
    }
    for (const name of COLOR_NAMES) {
      list.push([name, COLOR_LABELS_DE[name] || name, COLORS[name]]);
    }

    this.optionsList.replaceChildren(...list.map(([val, label, hex]) => {
      const isSel = (this.value || '') === val;
      const dot = h('span', { class: 'cp-dot', style: { background: hex } });
      const name = h('span', { class: 'cp-opt-name' }, label);
      const chk = isSel ? icon('mdi:check', 'cp-check') : null;
      return h('div', {
        class: 'cp-item', ...(isSel ? { 'data-active': '' } : {}),
        onClick: (e) => { e.stopPropagation(); this._setValue(val); },
      }, dot, name, chk);
    }));
  }
}
// ─── END: components/color_picker.js ───


// ─── START: components/custom_dropdown.js ───
// CustomDropdown: beautiful bespoke select component replacing native browser <select>.
// Features: custom styling, icons, color dots, optional search, keyboard & click-outside handling.
class CustomDropdown {
  /**
   * @param {{
   *   options: Array<{value: string, label: string, icon?: string, color?: string, sub?: string}>,
   *   value: string,
   *   placeholder?: string,
   *   disabled?: boolean,
   *   searchable?: boolean,
   *   onChange: (val: string) => void
   * }} opts
   */
  constructor({ options, items, value, placeholder = 'Bitte wählen...', disabled = false, searchable, onChange }) {
    const raw = options || items || [];
    this.options = raw.map((o) => ({
      ...o,
      value: String(o.value !== undefined ? o.value : (o.id !== undefined ? o.id : '')),
      label: String(o.label || o.name || ''),
    }));
    this.value = String(value !== undefined && value !== null ? value : '');
    this.placeholder = placeholder;
    this.disabled = disabled;
    this.searchable = searchable !== undefined ? searchable : this.options.length > 5;
    this.onChange = onChange;
    this.isOpen = false;
    this.searchQuery = '';

    this._onDocClick = (e) => {
      if (!this.isOpen) return;
      if (!e.composedPath().includes(this.el)) {
        this.close();
      }
    };
    document.addEventListener('click', this._onDocClick);

    this._build();
  }

  destroy() {
    document.removeEventListener('click', this._onDocClick);
  }

  setDisabled(disabled) {
    this.disabled = !!disabled;
    this.box.classList.toggle('disabled', this.disabled);
    if (this.disabled) this.close();
  }

  setValue(val) {
    this.value = String(val !== undefined && val !== null ? val : '');
    this._updateSelected();
  }

  setOptions(opts) {
    const raw = opts || [];
    this.options = raw.map((o) => ({
      ...o,
      value: String(o.value !== undefined ? o.value : (o.id !== undefined ? o.id : '')),
      label: String(o.label || o.name || ''),
    }));
    this.searchable = this.options.length > 5;
    this._updateSelected();
    if (this.isOpen) this._renderMenu();
  }

  _build() {
    this.iconEl = h('div', { class: 'cdd-icon', hidden: true });
    this.textEl = h('div', { class: 'cdd-text' }, this.placeholder);
    this.chevron = icon('mdi:chevron-down', 'cdd-chevron');

    this.box = h('div', {
      class: `cdd-box${this.disabled ? ' disabled' : ''}`,
      role: 'combobox',
      tabindex: this.disabled ? '-1' : '0',
      'aria-expanded': 'false',
      onClick: (e) => {
        e.stopPropagation();
        if (this.disabled) return;
        this.toggle();
      },
      onKeydown: (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          this.toggle();
        } else if (e.key === 'Escape') {
          this.close();
        }
      },
    }, this.iconEl, this.textEl, this.chevron);

    this.menu = h('div', { class: 'cdd-menu', hidden: true });

    this.el = h('div', { class: 'custom-dropdown' }, this.box, this.menu);
    this._updateSelected();
  }

  _updateSelected() {
    const sel = this.options.find((o) => o.value === this.value);
    if (sel) {
      this.textEl.textContent = sel.label;
      this.textEl.classList.remove('placeholder');
      if (sel.icon) {
        this.iconEl.replaceChildren(icon(sel.icon));
        if (sel.color) this.iconEl.style.color = sel.color;
        else this.iconEl.style.color = '';
        this.iconEl.hidden = false;
      } else if (sel.color) {
        const dot = h('span', { class: 'cdd-dot', style: { background: sel.color } });
        this.iconEl.replaceChildren(dot);
        this.iconEl.hidden = false;
      } else {
        this.iconEl.hidden = true;
      }
    } else {
      this.textEl.textContent = this.placeholder;
      this.textEl.classList.add('placeholder');
      this.iconEl.hidden = true;
    }
  }

  toggle() {
    if (this.isOpen) this.close();
    else this.open();
  }

  open() {
    if (this.disabled || this.isOpen) return;
    this.isOpen = true;
    this.box.dataset.open = '';
    this.box.setAttribute('aria-expanded', 'true');
    this.menu.hidden = false;
    this.searchQuery = '';
    this._renderMenu();

    if (this.searchInput) {
      setTimeout(() => {
        this.searchInput.focus();
        const rect = this.menu.getBoundingClientRect();
        if (rect.bottom > window.innerHeight - 30) {
          this.el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }
      }, 30);
    } else {
      setTimeout(() => {
        const rect = this.menu.getBoundingClientRect();
        if (rect.bottom > window.innerHeight - 30) {
          this.el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }
      }, 30);
    }
  }

  close() {
    if (!this.isOpen) return;
    this.isOpen = false;
    delete this.box.dataset.open;
    this.box.setAttribute('aria-expanded', 'false');
    this.menu.hidden = true;
  }

  _renderMenu() {
    const q = this.searchQuery.toLowerCase().trim();
    const filtered = q
      ? this.options.filter((o) => o.label.toLowerCase().includes(q) || (o.sub && o.sub.toLowerCase().includes(q)))
      : this.options;

    const items = [];

    if (this.searchable) {
      this.searchInput = h('input', {
        type: 'text',
        class: 'cdd-search-input',
        placeholder: 'Suchen...',
        value: this.searchQuery,
        onClick: (e) => e.stopPropagation(),
        onInput: (e) => {
          this.searchQuery = e.target.value;
          this._renderMenu();
        },
      });
      const searchRow = h('div', { class: 'cdd-search-row' }, icon('mdi:magnify'), this.searchInput);
      items.push(searchRow);
    }

    const list = h('div', { class: 'cdd-list' });

    if (!filtered.length) {
      list.append(h('div', { class: 'cdd-empty' }, 'Keine Optionen gefunden'));
    } else {
      for (const opt of filtered) {
        const isSelected = opt.value === this.value;
        const iconWrap = h('div', { class: 'cdd-item-icon' });
        if (opt.icon) {
          iconWrap.append(icon(opt.icon));
          if (opt.color) iconWrap.style.color = opt.color;
        } else if (opt.color) {
          iconWrap.append(h('span', { class: 'cdd-dot', style: { background: opt.color } }));
        } else {
          iconWrap.style.display = 'none';
        }

        const labelWrap = h('div', { class: 'cdd-item-texts' },
          h('div', { class: 'cdd-item-label' }, opt.label),
          opt.sub ? h('div', { class: 'cdd-item-sub' }, opt.sub) : null);

        const checkWrap = h('div', { class: 'cdd-item-check' });
        if (isSelected) checkWrap.append(icon('mdi:check'));

        const item = h('div', {
          class: `cdd-item${isSelected ? ' selected' : ''}`,
          onClick: (e) => {
            e.stopPropagation();
            this.value = opt.value;
            this._updateSelected();
            this.close();
            this.onChange?.(opt.value);
          },
        }, iconWrap, labelWrap, checkWrap);

        list.append(item);
      }
    }

    items.push(list);
    this.menu.replaceChildren(...items);
  }
}
// ─── END: components/custom_dropdown.js ───


// ─── START: components/icon_picker.js ───
// Rich Icon Picker for Companion Dashboard (HA-style single-input search across all MDI icons).
let _mdiCatalog = null;
let _mdiLoadPromise = null;

function _buildBaseCatalog(hass) {
  const seen = new Set();
  const list = [];

  for (const item of POPULAR_ICONS) {
    const ic = typeof item === 'string' ? item : item?.icon;
    if (!ic || seen.has(ic)) continue;
    seen.add(ic);
    const label = (typeof item === 'object' && item?.name) ? item.name : ic.replace(/^mdi:/, '');
    const tags = (typeof item === 'object' && item?.cat) ? item.cat.toLowerCase() : '';
    list.push({ icon: ic, label, search: `${ic} ${label} ${tags}`.toLowerCase() });
  }

  if (hass?.states) {
    for (const st of Object.values(hass.states)) {
      const ic = st?.attributes?.icon;
      if (typeof ic === 'string' && ic.startsWith('mdi:') && !seen.has(ic)) {
        seen.add(ic);
        const slug = ic.slice(4);
        list.push({ icon: ic, label: slug, search: ic.toLowerCase() });
      }
    }
  }

  return { seen, list };
}

async function _loadFullMdiCatalog(hass) {
  if (_mdiCatalog) return _mdiCatalog;
  if (_mdiLoadPromise) return _mdiLoadPromise;

  _mdiLoadPromise = (async () => {
    const { seen, list } = _buildBaseCatalog(hass);
    try {
      const resp = await fetch('/static/mdi/iconList.json', { credentials: 'same-origin' });
      if (resp.ok) {
        const data = await resp.json();
        if (Array.isArray(data)) {
          for (const entry of data) {
            const rawName = typeof entry === 'string' ? entry : entry?.name;
            if (!rawName) continue;
            const ic = rawName.startsWith('mdi:') ? rawName : `mdi:${rawName}`;
            if (seen.has(ic)) continue;
            seen.add(ic);
            const slug = ic.slice(4);
            const kw = Array.isArray(entry?.keywords) ? entry.keywords.join(' ') : '';
            list.push({
              icon: ic,
              label: slug,
              search: `${ic} ${kw}`.toLowerCase(),
            });
          }
        }
      }
    } catch (_) {
      // Offline / dev mock fallback: base catalog + HA state icons already loaded
    }
    _mdiCatalog = list;
    return _mdiCatalog;
  })();

  return _mdiLoadPromise;
}
class IconPicker {
  constructor({ hass, value = '', onChange, placeholder = 'Icon suchen (z. B. Lampe, mdi:bed)...' }) {
    this.hass = hass;
    this.value = value || '';
    this.onChange = onChange;
    this.placeholder = placeholder;
    this.isOpen = false;
    this.searchQuery = '';
    this._catalog = _mdiCatalog || _buildBaseCatalog(hass).list;

    this._onDocClick = (e) => {
      if (!e.composedPath().includes(this.el)) this._close();
    };

    this._build();

    // Preload full HA MDI catalog in background
    _loadFullMdiCatalog(this.hass).then((catalog) => {
      this._catalog = catalog;
      if (this.isOpen) this._renderGrid();
    });
  }

  _build() {
    this.previewIcon = h('div', {
      class: 'ip-preview',
      onClick: (e) => { e.stopPropagation(); this._toggle(); },
    });

    this.textInput = h('input', {
      type: 'text',
      class: 'ip-input',
      value: this.value,
      placeholder: this.placeholder,
      autocomplete: 'off',
      spellcheck: 'false',
      onInput: (e) => {
        const raw = e.target.value.trim();
        this.value = raw;
        this.searchQuery = raw.replace(/^mdi:/i, '').toLowerCase();
        this._updatePreview();
        this._updateClearBtn();
        if (!this.isOpen) this._open(false);
        else this._renderGrid();
        this.onChange?.(this.value);
      },
      onFocus: () => {
        if (!this.isOpen) {
          this.searchQuery = '';
          this._open(true);
        }
      },
      onClick: (e) => {
        e.stopPropagation();
        if (!this.isOpen) {
          this.searchQuery = '';
          this._open(true);
        }
      },
    });

    this.clearBtn = h('button', {
      type: 'button',
      class: 'ip-clear',
      'aria-label': 'Eingabe löschen',
      title: 'Löschen & alle Icons anzeigen',
      hidden: !this.value,
      onClick: (e) => {
        e.stopPropagation();
        this.value = '';
        this.textInput.value = '';
        this.searchQuery = '';
        this._updatePreview();
        this._updateClearBtn();
        this.onChange?.('');
        if (!this.isOpen) this._open(false);
        else this._renderGrid();
        this.textInput.focus();
      },
    }, icon('mdi:close'));

    this.toggleBtn = h('button', {
      type: 'button',
      class: 'ip-toggle',
      'aria-label': 'Icon auswählen',
      onClick: (e) => { e.stopPropagation(); this._toggle(); },
    }, icon('mdi:chevron-down'));

    this.box = h('div', { class: 'ip-box' }, this.previewIcon, this.textInput, this.clearBtn, this.toggleBtn);

    this.statusEl = h('div', { class: 'ip-status' });
    this.grid = h('div', { class: 'ip-grid' });
    this.dropdown = h('div', { class: 'ip-dropdown', hidden: true }, this.statusEl, this.grid);

    this.el = h('div', { class: 'icon-picker' }, this.box, this.dropdown);
    this._updatePreview();
  }

  _updateClearBtn() {
    this.clearBtn.hidden = !this.textInput.value;
  }

  _setValue(val) {
    this.value = val;
    this.textInput.value = val;
    this._updatePreview();
    this._updateClearBtn();
    this.onChange?.(val);
    this._close();
  }

  _updatePreview() {
    const ic = this.value && this.value.includes(':') ? this.value : 'mdi:star-four-points-outline';
    this.previewIcon.replaceChildren(icon(ic));
  }

  _toggle() {
    if (this.isOpen) this._close();
    else {
      this.searchQuery = '';
      this._open(true);
    }
  }

  _open(selectInput = false) {
    if (this.isOpen) return;
    this.isOpen = true;
    this.dropdown.hidden = false;
    this.box.dataset.open = '';
    this._renderGrid();
    setTimeout(() => {
      if (selectInput) {
        this.textInput.focus();
        if (this.textInput.value) this.textInput.select();
      }
      document.addEventListener('pointerdown', this._onDocClick);
    }, 10);
  }

  _close() {
    if (!this.isOpen) return;
    this.isOpen = false;
    this.dropdown.hidden = true;
    delete this.box.dataset.open;
    document.removeEventListener('pointerdown', this._onDocClick);
  }

  _renderGrid() {
    const q = this.searchQuery;
    const filtered = q
      ? this._catalog.filter((entry) => entry.search.includes(q))
      : this._catalog;

    const maxVisible = 80;
    const visible = filtered.slice(0, maxVisible);

    if (q) {
      this.statusEl.textContent = filtered.length > maxVisible
        ? `${maxVisible} von ${filtered.length} Treffern – weiter tippen zum Eingrenzen`
        : `${filtered.length} Treffer`;
    } else {
      this.statusEl.textContent = `${this._catalog.length} Icons verfügbar · Direkt oben tippen zum Suchen`;
    }

    const items = visible.map((entry) => {
      const isSel = this.value === entry.icon;
      return h('button', {
        type: 'button',
        class: `ip-chip${isSel ? ' active' : ''}`,
        title: `${entry.label} (${entry.icon})`,
        onClick: (e) => { e.stopPropagation(); this._setValue(entry.icon); },
      }, icon(entry.icon), h('span', { class: 'ip-chip-name' }, entry.label));
    });

    if (q) {
      const customMdi = `mdi:${q.replace(/\s+/g, '-')}`;
      if (!visible.some((entry) => entry.icon === customMdi)) {
        items.unshift(h('button', {
          type: 'button',
          class: 'ip-chip',
          title: customMdi,
          onClick: (e) => { e.stopPropagation(); this._setValue(customMdi); },
        }, icon(customMdi), h('span', { class: 'ip-chip-name' }, customMdi)));
      }
    }

    if (!items.length) {
      this.grid.replaceChildren(h('div', { class: 'ip-empty' }, 'Kein Icon gefunden – direkt „mdi:name“ eingeben'));
      return;
    }

    this.grid.replaceChildren(...items);
  }
}
// ─── END: components/icon_picker.js ───


// ─── START: components/entity_picker.js ───
// Rich Entity Picker for Companion Dashboard (Shadow-DOM safe, instant autocomplete).
const DOMAIN_LABELS_DE = {
  light: 'Lichter', switch: 'Schalter', sensor: 'Sensoren', binary_sensor: 'Binär',
  cover: 'Jalousien', media_player: 'Medien', climate: 'Klima', script: 'Skripte',
  scene: 'Szenen', input_boolean: 'Helfer', calendar: 'Kalender', device_tracker: 'Tracker',
  person: 'Personen', weather: 'Wetter', fan: 'Lüfter', valve: 'Ventile',
};
class EntityPicker {
  constructor({ hass, value = '', onChange, filter, domain, placeholder = 'Entität suchen...', allowClear = true }) {
    this.hass = hass;
    this.value = value || '';
    this.onChange = onChange;
    this.filter = filter;
    this.domains = domain ? (Array.isArray(domain) ? domain : [domain]) : null;
    this.placeholder = placeholder;
    this.allowClear = allowClear;

    this.isOpen = false;
    this.searchQuery = '';
    this.selectedDomain = 'all';

    // Use composedPath() so Shadow DOM retargeting never closes the dropdown on inner clicks
    this._onDocClick = (e) => {
      if (!e.composedPath().includes(this.el)) this._close();
    };

    this._build();
  }

  _build() {
    this.boxIcon = h('div', { class: 'ep-icon' });
    this.boxTitle = h('div', { class: 'ep-title' });
    this.boxSub = h('div', { class: 'ep-sub' });
    this.boxContent = h('div', { class: 'ep-content' }, this.boxTitle, this.boxSub);

    this.clearBtn = h('button', {
      type: 'button', class: 'ep-clear', 'aria-label': 'Löschen',
      onClick: (e) => { e.stopPropagation(); this._setValue(''); },
    }, icon('mdi:close'));

    this.chevron = icon('mdi:chevron-down', 'ep-chevron');

    this.box = h('div', {
      class: 'ep-box', tabindex: '0', role: 'combobox', 'aria-expanded': 'false',
      onClick: (e) => { e.stopPropagation(); this._toggle(); },
      onKeydown: (e) => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); this._toggle(); }
        else if (e.key === 'Escape') { this._close(); }
        else if (e.key.length === 1 && !e.ctrlKey && !e.metaKey) {
          this._open(e.key);
        }
      },
    }, this.boxIcon, this.boxContent, this.clearBtn, this.chevron);

    // Dropdown popover
    this.searchInput = h('input', {
      type: 'text', class: 'ep-search-input', placeholder: 'Name, Raum oder entity_id eintippen...',
      onInput: (e) => { this.searchQuery = e.target.value.toLowerCase().trim(); this._updateList(); },
      onKeydown: (e) => {
        if (e.key === 'Escape') { e.stopPropagation(); this._close(); }
        else if (e.key === 'ArrowDown') { e.preventDefault(); this._focusFirstItem(); }
        else if (e.key === 'Enter') {
          e.preventDefault();
          const first = this.listEl.querySelector('.ep-item');
          if (first) first.click();
          else if (this.searchInput.value.includes('.')) this._setValue(this.searchInput.value.trim());
        }
      },
    });

    this.searchRow = h('div', { class: 'ep-search' }, icon('mdi:magnify'), this.searchInput);
    this.chipsRow = h('div', { class: 'ep-chips' });
    this.listEl = h('div', { class: 'ep-list' });

    this.dropdown = h('div', { class: 'ep-dropdown', hidden: true },
      this.searchRow,
      this.chipsRow,
      this.listEl);

    this.el = h('div', { class: 'entity-picker' }, this.box, this.dropdown);

    this._updateBox();
  }

  _setValue(val) {
    this.value = val;
    this._updateBox();
    this.onChange?.(val);
    this._close();
  }

  _updateBox() {
    const st = this.value ? this.hass?.states?.[this.value] : null;
    const hasVal = !!this.value;

    this.clearBtn.hidden = !hasVal || !this.allowClear;

    if (hasVal) {
      const name = st?.attributes?.friendly_name || this.value;
      const ic = entityIcon(this.value, st);
      this.boxIcon.replaceChildren(icon(ic));
      this.boxTitle.textContent = name;
      this.boxTitle.classList.remove('ep-placeholder');
      this.boxSub.textContent = this.value;
      this.boxSub.hidden = false;
    } else {
      this.boxIcon.replaceChildren(icon('mdi:magnify'));
      this.boxTitle.textContent = this.placeholder;
      this.boxTitle.classList.add('ep-placeholder');
      this.boxSub.textContent = '';
      this.boxSub.hidden = true;
    }
  }

  _toggle() {
    if (this.isOpen) this._close();
    else this._open();
  }

  _open(initialChar = '') {
    if (this.isOpen) return;
    this.isOpen = true;
    this.dropdown.hidden = false;
    this.box.dataset.open = '';
    this.box.setAttribute('aria-expanded', 'true');
    this.searchQuery = initialChar.toLowerCase();
    this.searchInput.value = initialChar;
    this._renderDomainChips();
    this._updateList();

    setTimeout(() => {
      this.searchInput.focus();
      document.addEventListener('pointerdown', this._onDocClick);
      const rect = this.dropdown.getBoundingClientRect();
      if (rect.bottom > window.innerHeight - 30) {
        this.el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    }, 20);
  }

  _close() {
    if (!this.isOpen) return;
    this.isOpen = false;
    this.dropdown.hidden = true;
    delete this.box.dataset.open;
    this.box.setAttribute('aria-expanded', 'false');
    document.removeEventListener('pointerdown', this._onDocClick);
  }

  _getAvailableEntities() {
    const states = this.hass?.states || {};
    const entries = [];

    for (const [entityId, st] of Object.entries(states)) {
      const d = domainOf(entityId);
      if (this.domains && !this.domains.includes(d)) continue;
      if (this.filter && !this.filter(entityId, st)) continue;
      entries.push({ entityId, st, domain: d });
    }

    return entries;
  }

  _renderDomainChips() {
    const all = this._getAvailableEntities();
    const domainCounts = new Map();
    for (const { domain } of all) {
      domainCounts.set(domain, (domainCounts.get(domain) || 0) + 1);
    }

    if (domainCounts.size <= 1) {
      this.chipsRow.hidden = true;
      return;
    }
    this.chipsRow.hidden = false;

    const chips = [['all', `Alle (${all.length})`]];
    for (const [dom, count] of Array.from(domainCounts.entries()).sort((a, b) => b[1] - a[1]).slice(0, 6)) {
      const label = DOMAIN_LABELS_DE[dom] || dom;
      chips.push([dom, `${label} (${count})`]);
    }

    this.chipsRow.replaceChildren(...chips.map(([id, label]) => h('button', {
      type: 'button', class: 'filter-chip', ...(id === this.selectedDomain ? { 'data-active': '' } : {}),
      onClick: (e) => {
        e.stopPropagation();
        this.selectedDomain = id;
        this._renderDomainChips();
        this._updateList();
      },
    }, label)));
  }

  _updateList() {
    const all = this._getAvailableEntities();
    const q = this.searchQuery;
    const dom = this.selectedDomain;

    const filtered = all.filter(({ entityId, st, domain }) => {
      if (dom !== 'all' && domain !== dom) return false;
      if (!q) return true;
      const fn = (st?.attributes?.friendly_name || '').toLowerCase();
      return entityId.toLowerCase().includes(q) || fn.includes(q);
    });

    if (!filtered.length) {
      this.listEl.replaceChildren(h('div', { class: 'empty', style: { padding: '20px 12px' } },
        icon('mdi:file-search-outline'),
        h('div', { style: { fontSize: '12px', marginTop: '4px' } }, 'Keine passenden Entitäten gefunden')));
      return;
    }

    filtered.sort((a, b) => {
      if (a.entityId === this.value) return -1;
      if (b.entityId === this.value) return 1;
      const an = (a.st?.attributes?.friendly_name || a.entityId).toLowerCase();
      const bn = (b.st?.attributes?.friendly_name || b.entityId).toLowerCase();
      if (q) {
        const aStarts = an.startsWith(q) || a.entityId.toLowerCase().startsWith(q);
        const bStarts = bn.startsWith(q) || b.entityId.toLowerCase().startsWith(q);
        if (aStarts !== bStarts) return aStarts ? -1 : 1;
      }
      return an.localeCompare(bn);
    });

    this.listEl.replaceChildren(...filtered.slice(0, 80).map(({ entityId, st }) => {
      const isSel = entityId === this.value;
      const name = st?.attributes?.friendly_name || entityId;
      const ic = entityIcon(entityId, st);
      const stateTxt = stateLabel(this.hass, st);

      return h('div', {
        class: 'ep-item', ...(isSel ? { 'data-active': '' } : {}),
        tabindex: '0', role: 'option', 'aria-selected': String(isSel),
        onClick: (e) => { e.stopPropagation(); this._setValue(entityId); },
        onKeydown: (e) => {
          if (e.key === 'Enter') { e.preventDefault(); e.stopPropagation(); this._setValue(entityId); }
        },
      },
      icon(ic),
      h('div', { class: 'ep-content' },
        h('div', { class: 'ep-title' }, name),
        h('div', { class: 'ep-sub' }, entityId)),
      stateTxt ? h('span', { class: 'item-state' }, stateTxt) : null,
      isSel ? icon('mdi:check', 'ep-check') : null);
    }));
  }

  _focusFirstItem() {
    this.listEl.querySelector('.ep-item')?.focus();
  }
}
// ─── END: components/entity_picker.js ───


// ─── START: components/tile.js ───
// Tile component: one entity as a HA-tile-like card (lights, switches, covers, climate, media, sensors).
const COLOR_MODES = ['hs', 'xy', 'rgb', 'rgbw', 'rgbww'];

function lightSupport(st) {
  const modes = st?.attributes?.supported_color_modes || [];
  return {
    brightness: modes.some((m) => m !== 'onoff'),
    color: modes.some((m) => COLOR_MODES.includes(m)),
  };
}
class Tile {
  /**
   * @param {object} spec   tile from the backend layout {key, entity_id, name, icon, color, power}
   * @param {object} ctx    {presets: number[][]}
   */
  constructor(spec, ctx) {
    this.spec = spec;
    this.ctx = ctx;
    this.entityId = spec.entity_id;
    this.deviceId = spec.device_id || (spec.key && spec.key.includes(':') && !spec.key.startsWith('e:') && !spec.key.startsWith('l:') ? spec.key.split(':')[0] : null) || spec.entity_id;
    this.rawDomain = domainOf(spec.entity_id);
    const cat = effectiveCategory(spec);
    // Effective domain overrides raw domain for UI purposes
    this.domain = (cat === 'light' || cat === 'cover' || cat === 'media_player' || cat === 'climate' || cat === 'valve' || cat === 'pumpe' || cat === 'motion' || cat === 'sensor' || cat === 'outlet' || cat === 'switch')
      ? cat : this.rawDomain;
    this.kind = ['cover', 'media_player', 'climate', 'sensor', 'binary_sensor', 'motion'].includes(this.domain)
      ? (this.domain === 'motion' ? 'sensor' : this.domain) : 'toggle';
    this.hass = null;
    this._st = undefined;
    this._pw = undefined;
    this._presetKey = '';
    this._build();
  }

  _build() {
    this.iconEl = icon('mdi:bookmark');
    this.iconBtn = h('button', {
      class: 'tile-icon', 'aria-label': 'Schalten',
      onClick: (e) => { e.stopPropagation(); this._onIcon(); },
    }, this.iconEl);
    this.nameEl = h('div', { class: 'tile-name' });
    this.stateEl = h('div', { class: 'tile-state' });
    this.info = h('div', {
      class: 'tile-info',
      onClick: () => {
        if (this.ctx?.isEditMode?.()) {
          const targetId = this.deviceId || this.spec?.device_id || this.entityId;
          this.ctx.onOpenDevice?.(targetId);
          return;
        }
        moreInfo(this.el, this.entityId);
      },
    }, this.nameEl, this.stateEl);
    this.btns = h('div', { class: 'tile-btns' });
    this.feature = h('div', { class: 'tile-feature', hidden: true });

    const wide = ['cover', 'media_player', 'climate'].includes(this.kind);
    this.el = h('div', { class: `tile ${this.kind}${wide ? ' wide' : ''}`, 'data-key': this.spec.key },
      h('div', { class: 'tile-main' }, this.iconBtn, this.info, this.btns),
      this.feature);

    this.el.addEventListener('click', (e) => {
      if (this.ctx?.isEditMode?.()) {
        e.stopPropagation();
        e.preventDefault();
        const targetId = this.deviceId || this.spec?.device_id || this.entityId;
        this.ctx.onOpenDevice?.(targetId);
      }
    }, true);

    if (this.kind === 'cover') this._buildCover();
    if (this.kind === 'media_player') this._buildMedia();
    if (this.domain === 'light') this._buildLightFeature();
  }

  // ── builders ──
  _service(domain, service, data = {}) {
    if (domain === 'cover' && this.rawDomain !== 'cover') {
      if (service === 'open_cover') return this.hass?.callService(this.rawDomain, 'turn_on', { entity_id: this.entityId });
      if (service === 'close_cover') return this.hass?.callService(this.rawDomain, 'turn_off', { entity_id: this.entityId });
      if (service === 'stop_cover') return this.hass?.callService(this.rawDomain, 'turn_off', { entity_id: this.entityId });
    }
    return this.hass?.callService(domain, service, { entity_id: this.entityId, ...data });
  }

  _buildCover() {
    const mk = (ic, label, fn) => h('button', { class: 'mini-btn', 'aria-label': label, onClick: (e) => { e.stopPropagation(); fn(); } }, icon(ic));
    this.btnUp = mk('mdi:arrow-up', 'Öffnen', () => this._service('cover', 'open_cover'));
    this.btnStop = mk('mdi:stop', 'Stopp', () => this._service('cover', 'stop_cover'));
    this.btnDown = mk('mdi:arrow-down', 'Schließen', () => this._service('cover', 'close_cover'));
    this.btns.append(this.btnUp, this.btnStop, this.btnDown);
  }

  _buildMedia() {
    this.btnPlay = h('button', {
      class: 'mini-btn', 'aria-label': 'Wiedergabe',
      onClick: (e) => { e.stopPropagation(); this._service('media_player', 'media_play_pause'); },
    }, icon('mdi:play-pause'));
    this.btns.append(this.btnPlay);
    this.el.classList.add('media');
  }

  get hasSlider() {
    if (this.domain === 'light') {
      const { brightness } = lightSupport(this._st);
      return !!brightness;
    }
    return false;
  }

  get isAlwaysWide() {
    return ['cover', 'media_player', 'climate'].includes(this.kind)
      || this.spec.is_group === true
      || this.spec.wide === true;
  }

  get isWide() {
    return this.el.classList.contains('wide');
  }

  setWide(wide) {
    this.el.classList.toggle('wide', !!wide);
  }

  _buildLightFeature() {
    this.slider = h('input', {
      type: 'range', class: 'slider', min: '1', max: '100', step: '1', 'aria-label': 'Helligkeit',
      style: { touchAction: 'none' },
    });
    // Prevent vertical page scroll during slider touch interaction
    this.slider.addEventListener('pointerdown', (e) => e.stopPropagation());
    this.slider.addEventListener('touchstart', (e) => e.stopPropagation(), { passive: true });
    this.slider.addEventListener('touchmove', (e) => e.stopPropagation(), { passive: true });
    this.slider.addEventListener('input', () => {
      this._dragging = true;
      setSliderVal(this.slider, this.slider.value);
    });
    this.slider.addEventListener('change', () => {
      this._dragging = false;
      this._service('light', 'turn_on', { brightness_pct: Number(this.slider.value) });
    });
    this.swatches = h('div', { style: { display: 'flex', gap: '8px' } });
    this.feature.append(this.slider, this.swatches);
  }

  _renderPresets() {
    const presets = this.ctx.presets || [];
    const key = JSON.stringify(presets);
    if (key === this._presetKey) return;
    this._presetKey = key;
    this.swatches.replaceChildren(...presets.map((rgb) => h('button', {
      class: 'swatch', 'aria-label': `Farbe ${rgb.join(',')}`,
      style: { background: `rgb(${rgb.join(',')})` },
      onClick: (e) => {
        e.stopPropagation();
        const br = this._st?.attributes?.brightness || 255;
        this._service('light', 'turn_on', { rgb_color: rgb, brightness: br });
      },
    })));
  }

  _onIcon() {
    if (this.ctx?.isEditMode?.()) {
      const targetId = this.deviceId || this.spec?.device_id || this.entityId;
      this.ctx.onOpenDevice?.(targetId);
      return;
    }
    if (!this.hass) return;
    if (this.kind === 'sensor' || this.kind === 'binary_sensor' || this.domain === 'sensor' || this.domain === 'motion' || !isToggleable(this.entityId)) {
      moreInfo(this.el, this.entityId);
    } else {
      toggleEntity(this.hass, this.entityId);
    }
  }

  // ── state ──
  _active(st) {
    if (this.spec.category === 'jalousie' || this.domain === 'cover') {
      return !!st && st.state !== 'closed' && !isUnavailable(st);
    }
    switch (this.domain) {
      case 'climate': return !!st && st.state !== 'off' && !isUnavailable(st);
      case 'media_player': return !!st && !['off', 'standby', 'idle', 'unavailable', 'unknown'].includes(st.state);
      case 'sensor': return false;
      case 'motion': return !!st && (st.state === 'on' || st.state === 'detected' || st.state === 'motion');
      case 'valve': return !!st && (st.state === 'on' || st.state === 'open');
      case 'pumpe': return !!st && st.state === 'on';
      default: return isActive(st);
    }
  }

  update(hass) {
    this.hass = hass;
    const st = hass.states[this.entityId];
    const pw = this.spec.power ? hass.states[this.spec.power] : null;
    const stateKey = `${st?.state}|${st?.attributes?.brightness}|${st?.attributes?.current_position}|${st?.attributes?.rgb_color}|${st?.last_updated}|${pw?.state}`;
    if (this._rendered && this._stateKey === stateKey) return;
    this._rendered = true;
    this._stateKey = stateKey;
    this._st = st;
    this._pw = pw;

    const attrs = st?.attributes || {};
    const unavailable = isUnavailable(st);
    const active = this._active(st);
    this.el.toggleAttribute('data-unavailable', unavailable);
    this.el.dataset.active = String(active);

    // Name
    this.nameEl.textContent = this.spec.name || attrs.friendly_name || this.entityId;

    // Icon + colour
    this.iconEl.setAttribute('icon', entityIcon(this.entityId, st, this.spec.icon, this.spec.category));
    let color = '';
    if (active) {
      color = getEntityColor(this.entityId, st, this.spec.category, this.spec.color);
    }
    if (color) this.el.style.setProperty('--tile-color', color); else this.el.style.removeProperty('--tile-color');

    // State text
    this.stateEl.textContent = this._stateText(hass, st, pw, active);

    // Kind specifics
    if (this.kind === 'cover') this._updateCover(st, unavailable);
    if (this.kind === 'media_player') this._updateMedia(st, unavailable);
    if (this.domain === 'light') this._updateLight(st, active);
  }

  _stateText(hass, st, pw, active) {
    if (!st) return 'Nicht gefunden';
    const attrs = st.attributes || {};
    let text = stateLabel(hass, st, this.spec.category);
    if (this.domain === 'cover' && typeof attrs.current_position === 'number' && st.state !== 'closed' && st.state !== 'open') {
      text += ` · ${attrs.current_position} %`;
    } else if (this.domain === 'light' && active && typeof attrs.brightness === 'number') {
      text += ` · ${Math.round((attrs.brightness / 255) * 100)} %`;
    } else if (this.domain === 'climate') {
      const cur = attrs.current_temperature;
      const tgt = attrs.temperature;
      if (cur != null) text += ` · ${cur}°`;
      if (tgt != null && st.state !== 'off') text += ` → ${tgt}°`;
    } else if (this.domain === 'media_player' && ['playing', 'paused'].includes(st.state) && attrs.media_title) {
      text = [attrs.media_title, attrs.media_artist].filter(Boolean).join(' – ');
    }
    const watts = numeric(pw);
    if (watts !== null && watts > 0 && active) text += ` · ${watts % 1 ? watts.toFixed(1) : watts} W`;
    return text;
  }

  _updateCover(st, unavailable) {
    const state = st?.state;
    const moving = state === 'opening' || state === 'closing';
    this.btnUp.disabled = unavailable;
    this.btnDown.disabled = unavailable;
    this.btnStop.disabled = unavailable;
    this.btnStop.hidden = false;
    if (moving) {
      this.btnStop.style.color = 'var(--cd-active, #ffc107)';
      this.btnStop.style.background = 'color-mix(in srgb, var(--cd-active) 25%, transparent)';
    } else {
      this.btnStop.style.color = '';
      this.btnStop.style.background = '';
    }
  }

  _updateMedia(st, unavailable) {
    const art = st?.attributes?.entity_picture;
    const playing = !!st && ['playing', 'paused'].includes(st.state);
    if (art && playing) {
      this.el.style.backgroundImage = `url("${art}")`;
      this.el.dataset.art = '1';
    } else {
      this.el.style.backgroundImage = '';
      delete this.el.dataset.art;
    }
    this.btnPlay.disabled = unavailable || st?.state === 'off';
    this.btnPlay.firstChild?.setAttribute('icon', st?.state === 'playing' ? 'mdi:pause' : 'mdi:play');
  }

  _updateLight(st, active) {
    const { brightness, color } = lightSupport(st);
    const presets = this.ctx.presets || [];
    const showSlider = active && brightness;
    const showSwatches = active && color && presets.length > 0;
    const hasFeature = showSlider || showSwatches;
    this.feature.hidden = !hasFeature;
    if (!hasFeature) return;
    this.slider.hidden = !showSlider;
    this.swatches.hidden = !showSwatches;
    if (showSwatches) this._renderPresets();
    if (showSlider && !this._dragging) {
      const pct = Math.max(1, Math.round(((st.attributes.brightness || 0) / 255) * 100));
      setSliderVal(this.slider, pct);
    }
  }
}

/**
 * Hierarchical Group Tile (e.g. Master Light Group with collapsible subgroups / child lamps).
 */
class GroupTile {
  /**
   * @param {object} spec  {key, group_id, name, category, icon, color, entity_ids, children}
   * @param {object} ctx
   */
  constructor(spec, ctx) {
    this.spec = spec;
    this.ctx = ctx;
    this.isSubGroup = !!ctx?.isSubGroup;
    this.entityIds = spec.entity_ids || [];
    this.category = spec.category || 'leuchte';
    this.domain = this.category === 'leuchte' ? 'light' : 'switch';
    this.hass = null;
    this._open = false;
    this._dragging = false;

    // Sub-groups inside a group NEVER have children or nested accordions!
    if (this.isSubGroup) {
      this.children = [];
    } else {
      this.children = (spec.children || []).map((childSpec) => {
        if (childSpec.is_group) {
          return new GroupTile(childSpec, { ...ctx, isSubGroup: true });
        }
        return new Tile(childSpec, ctx);
      });
    }

    this._build();
  }

  get hasSlider() {
    return true;
  }

  get isAlwaysWide() {
    return !this.isSubGroup;
  }

  get isWide() {
    return !this.isSubGroup;
  }

  setWide(wide) {
    this.el.classList.toggle('wide', !!wide);
  }

  _build() {
    const isLeuchte = this.category === 'leuchte';
    const defaultIcon = isLeuchte ? 'mdi:lightbulb-group-outline' : 'mdi:power-plug-off';
    this.iconEl = icon(this.spec.icon ? `${this.spec.icon}-outline` : defaultIcon);

    this.iconBtn = h('button', {
      class: 'tile-icon group-icon-btn',
      'aria-label': `${this.spec.name} Schalten`,
      title: 'Alle ein-/ausschalten',
      onClick: (e) => {
        e.stopPropagation();
        this._toggleMaster();
      },
    }, this.iconEl);

    this.nameEl = h('div', { class: 'tile-name' }, this.spec.name);
    this.stateEl = h('div', { class: 'tile-state' }, 'Aus');

    const openGroupMoreInfo = () => {
      const targetEntity = this.spec.entity_id || this.entityIds[0];
      if (targetEntity) moreInfo(this.el, targetEntity);
    };

    this.info = h('div', {
      class: 'tile-info',
      title: 'Details öffnen',
      onClick: (e) => {
        e.stopPropagation();
        if (this.ctx?.isEditMode?.()) {
          this.ctx.onOpenGroup?.(this.spec.group_id);
          return;
        }
        openGroupMoreInfo();
      },
    }, this.nameEl, this.stateEl);

    if (this.isSubGroup) {
      this.btns = h('div', { class: 'tile-btns' });
    } else {
      this.chevron = icon('mdi:chevron-down');
      this.btnChevron = h('button', {
        type: 'button',
        class: 'mini-btn chevron-btn',
        'aria-label': 'Gruppe ausklappen',
        'aria-expanded': 'false',
        title: 'Unterlampen anzeigen',
        onClick: (e) => {
          e.stopPropagation();
          this._toggleOpen();
        },
      }, this.chevron);
      this.btns = h('div', { class: 'tile-btns' }, this.btnChevron);
    }

    // Master brightness slider
    this.feature = h('div', { class: 'tile-feature', hidden: true });
    this.slider = h('input', {
      type: 'range', class: 'slider', min: '1', max: '100', step: '1', 'aria-label': 'Gruppenhelligkeit',
      style: { touchAction: 'none' },
    });
    this.slider.addEventListener('pointerdown', (e) => e.stopPropagation());
    this.slider.addEventListener('input', () => {
      this._dragging = true;
      setSliderVal(this.slider, this.slider.value);
    });
    this.slider.addEventListener('change', () => {
      this._dragging = false;
      this._setMasterBrightness(Number(this.slider.value));
    });
    this.feature.append(this.slider);

    const mainRow = h('div', {
      class: 'tile-main',
      onClick: (e) => {
        if (e.target.closest('button')) return;
        if (this.ctx?.isEditMode?.()) {
          this.ctx.onOpenGroup?.(this.spec.group_id);
          return;
        }
        openGroupMoreInfo();
      },
    }, this.iconBtn, this.info, this.btns);

    if (this.isSubGroup) {
      this.el = h('div', {
        class: 'tile group subgroup',
        'data-key': this.spec.key,
        'data-group': 'true',
      }, mainRow, this.feature);
    } else {
      if (this.children.length % 2 === 1) {
        for (let i = 0; i < this.children.length - 1; i++) {
          this.children[i].setWide?.(false);
        }
        this.children[this.children.length - 1].setWide?.(true);
      } else {
        this.children.forEach((c) => c.setWide?.(false));
      }
      this.subGrid = h('div', { class: 'group-sub-grid' }, ...this.children.map((c) => c.el));
      this.subContainer = h('div', { class: 'group-sub-container' }, this.subGrid);
      this.subInner = h('div', { class: 'group-sub-inner' }, this.subContainer);
      this.subBody = h('div', { class: 'group-sub-body' }, this.subInner);
      this.el = h('div', {
        class: 'tile group wide',
        'data-key': this.spec.key,
        'data-group': 'true',
      }, mainRow, this.feature, this.subBody);
    }

    // Edit Mode click interception
    this.el.addEventListener('click', (e) => {
      if (this.ctx?.isEditMode?.()) {
        e.stopPropagation();
        e.preventDefault();
        this.ctx.onOpenGroup?.(this.spec.group_id);
      }
    }, true);
  }

  _toggleOpen() {
    if (this.isSubGroup) return;
    this._open = !this._open;
    this.el.toggleAttribute('data-open', this._open);
    this.btnChevron?.setAttribute('aria-expanded', String(this._open));
  }

  _toggleMaster() {
    if (!this.hass) return;
    const states = this.entityIds.map((id) => this.hass.states[id]).filter(Boolean);
    const anyOn = states.some((s) => s.state === 'on');
    const service = anyOn ? 'turn_off' : 'turn_on';
    const domain = this.domain;
    for (const eid of this.entityIds) {
      const d = domainOf(eid);
      this.hass.callService(d === 'light' || d === 'switch' ? d : domain, service, { entity_id: eid });
    }
  }

  _setMasterBrightness(pct) {
    if (!this.hass) return;
    for (const eid of this.entityIds) {
      if (domainOf(eid) === 'light') {
        this.hass.callService('light', 'turn_on', { entity_id: eid, brightness_pct: pct });
      }
    }
  }

  update(hass) {
    this.hass = hass;
    this.children.forEach((c) => c.update(hass));

    const states = this.entityIds.map((id) => hass.states[id]).filter(Boolean);
    const activeStates = states.filter((s) => s.state === 'on');
    const activeCount = activeStates.length;
    const anyOn = activeCount > 0;

    this.el.dataset.active = String(anyOn);
    this.iconBtn.classList.toggle('active', anyOn);

    if (anyOn) {
      const activeColor = this.spec.color || '#ffc107';
      this.el.style.setProperty('--tile-color', activeColor);
      this.iconEl.setAttribute('icon', this.spec.icon || (this.category === 'leuchte' ? 'mdi:lightbulb-group' : 'mdi:power-plug'));
    } else {
      this.el.style.removeProperty('--tile-color');
      const offIcon = this.spec.icon ? `${this.spec.icon}-outline` : (this.category === 'leuchte' ? 'mdi:lightbulb-group-outline' : 'mdi:power-plug-off');
      this.iconEl.setAttribute('icon', offIcon);
    }

    if (!states.length) {
      this.stateEl.textContent = 'Keine Entitäten';
    } else if (activeCount === 0) {
      this.stateEl.textContent = 'Aus';
    } else {
      const avgBr = this._avgBrightness(activeStates);
      this.stateEl.textContent = avgBr ? `Ein · ${avgBr} %` : 'Ein';
    }

    if (this.category === 'leuchte' && anyOn) {
      const avgBr = this._avgBrightness(activeStates);
      if (avgBr !== null) {
        this.feature.hidden = false;
        if (!this._dragging) {
          setSliderVal(this.slider, avgBr);
        }
      } else {
        this.feature.hidden = true;
      }
    } else {
      this.feature.hidden = true;
    }
  }

  _avgBrightness(activeStates) {
    const brs = activeStates
      .map((s) => s.attributes?.brightness)
      .filter((b) => typeof b === 'number');
    if (!brs.length) return null;
    const avg = Math.round(brs.reduce((a, b) => a + b, 0) / brs.length);
    return Math.max(1, Math.round((avg / 255) * 100));
  }
}
// ─── END: components/tile.js ───


